/**
 * Every script's Latin reading, per code point of the Basic Multilingual Plane: `reading:glyphs`
 * groups joined by `|`. Data, not code — installed as `bolt_search_romanize` so the lexical
 * document romanizes inside Postgres (generated column, raw-SQL seed loads and bulk writes alike).
 *
 * Han U+4E00–U+9FFF: toneless pinyin from pinyin-pro 3.29.4 (MIT), `pinyin(char, { toneType:
 * 'none', multiple: true, type: 'array' })`, at most two readings, the common one first (`sha xia`).
 * Every other code point: any-ascii 0.3.3 (ISC), lower-cased to [a-z0-9], kept only where that
 * differs from the glyph and the glyph survives `bolt_search_fold` unchanged (not a separator, not
 * folded away by NFKC, accent stripping or lower-casing). Generated once; regenerate by that rule.
 *
 * Shipped as raw DEFLATE in base64: uint32LE dictionary byte length, uint16LE first glyph,
 * pipe-separated UTF-8 readings in first-glyph order, then the high and low uint16 index
 * byte planes. The schema restores lexical reading order and the exact original SQL lookup.
 */
export const ROMANIZATION_DEFLATED =
	'';
